import re

from htmlbits.escape import escape

PLACEHOLDER = re.compile(r"\{(\w+)\}")


def render(template: str, **values: object) -> str:
    """Replace each {name} in template with escape(values[name]); a missing name raises KeyError."""

    def fill(match: re.Match[str]) -> str:
        value = values[match.group(1)]
        return "" if value is None else escape(value)

    return PLACEHOLDER.sub(fill, template)


def link(url: str, text: str) -> str:
    """An a element whose href and text are both escaped."""
    return f'<a href="{escape(url)}">{escape(text)}</a>'


def attrs(**values: object) -> str:
    """HTML attributes from keyword arguments, sorted by name: ' id="x" name="q"'."""
    parts = []
    for name, value in sorted(values.items()):
        if value is True:
            parts.append(f" {name}")
        elif value is not False and value is not None:
            parts.append(f' {name}="{escape(value)}"')
    return "".join(parts)

